# 1.2.高精度乘法

# 输入: 两个超大正整数 A 和 B
# 数据范围: 1 ≤ A的长度 ≤100000, 0 ≤ B的值 ≤10000
# 输出: A * B 的值

# 输入样例: 
# 
# 8110

# 输出样例:
# 

# 思路: 用数组储存每一位, 模拟乘法过程
def algorithm(A:str, B:str):
    # N位数 < 10^N, 故 (M位数 * N位数) < 10^(M+N)
    # 结果数组，长度仅需为 A 和 B 的长度之和
    result = [0] * (len(A) + len(str(B)))

    A = A[::-1]  # 反转A，方便从最低位开始乘法计算
    B = B[::-1]  # 反转B，方便从最低位开始乘法计算

    # 模拟乘法过程
    for i in range(len(A)):
        for j in range(len(B)):
            # 计算对应位的乘积
            product = int(A[i]) * int(B[j])
            # 将乘积加到结果数组的相应位置
            result[i + j] += product

    # 处理进位
    for i in range(len(result) - 1):
        if result[i] >= 10:
            result[i + 1] += result[i] // 10
            result[i] %= 10

    # 去除前导零
    while len(result) > 1 and result[-1] == 0:
        result.pop()

    # 反转并输出
    return ''.join(map(str, reversed(result)))

def main():
    #输入处理
    A = input().strip()
    B = input().strip()
    #执行算法
    print(algorithm(A, B))

def test():
    A = ""
    B = "8110"
    result = algorithm(A, B)
    print(result)
    assert result == ""
    print("Test passed.")

if __name__ == "__main__":
    test()
    main()